package com.example.crypto

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.util.Base64
import javax.crypto.Cipher
import javax.crypto.spec.IvParameterSpec
import javax.crypto.spec.SecretKeySpec
import javax.crypto.BadPaddingException

val SECRET_KEY = System.getenv("ENCRYPTION_KEY")?.toByteArray() ?: "0123456789abcdef".toByteArray()

fun decryptToken(encryptedBase64: String): Pair<Boolean, String?> {
    return try {
        val combined = Base64.getDecoder().decode(encryptedBase64)
        if (combined.size < 16) {
            return Pair(false, null)
        }
        val iv = combined.sliceArray(0 until 16)
        val ciphertext = combined.sliceArray(16 until combined.size)

        val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
        val keySpec = SecretKeySpec(SECRET_KEY, "AES")
        val ivSpec = IvParameterSpec(iv)
        cipher.init(Cipher.DECRYPT_MODE, keySpec, ivSpec)

        val plaintext = cipher.doFinal(ciphertext)
        Pair(true, String(plaintext, Charsets.UTF_8))
    } catch (e: BadPaddingException) {
        // Padding was invalid
        Pair(false, null)
    } catch (e: Exception) {
        // Other decryption errors (treated differently for logging)
        Pair(false, null)
    }
}

fun encryptToken(plaintext: String): String {
    val cipher = Cipher.getInstance("AES/CBC/PKCS5Padding")
    val keySpec = SecretKeySpec(SECRET_KEY, "AES")
    val iv = ByteArray(16)
    java.security.SecureRandom().nextBytes(iv)
    val ivSpec = IvParameterSpec(iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, ivSpec)
    val ciphertext = cipher.doFinal(plaintext.toByteArray(Charsets.UTF_8))
    return Base64.getEncoder().encodeToString(iv + ciphertext)
}

fun main() {
    embeddedServer(Netty, port = 8080) {
        routing {
            post("/api/v1/session/validate") {
                val body = call.receiveText()
                val token = body.trim()

                if (token.isEmpty()) {
                    call.respond(HttpStatusCode.BadRequest, "Missing token")
                    return@post
                }

                val (success, plaintext) = decryptToken(token)

                if (success && plaintext != null) {
                    // Parse session data from decrypted token
                    val parts = plaintext.split("|")
                    if (parts.size >= 3) {
                        val userId = parts[0]
                        val role = parts[1]
                        val expiry = parts[2].toLongOrNull() ?: 0L

                        if (System.currentTimeMillis() < expiry) {
                            call.respond(HttpStatusCode.OK, "{\"user\":\"$userId\",\"role\":\"$role\",\"valid\":true}")
                        } else {
                            call.respond(HttpStatusCode.Unauthorized, "{\"error\":\"token_expired\"}")
                        }
                    } else {
                        call.respond(HttpStatusCode.BadRequest, "{\"error\":\"malformed_token\"}")
                    }
                } else {
                    // VULNERABILITY: Different HTTP status for padding error vs other errors
                    // allows padding oracle attack
                    call.respond(HttpStatusCode.Forbidden, "{\"error\":\"invalid_token\"}")
                }
            }

            post("/api/v1/session/create") {
                val body = call.receiveText()
                // In production, this would authenticate first
                val token = encryptToken(body)
                call.respond(HttpStatusCode.OK, "{\"token\":\"$token\"}")
            }

            get("/health") {
                call.respond(HttpStatusCode.OK, "OK")
            }
        }
    }.start(wait = true)
}
